sql_calls.sql:
SELECT COUNT(*) AS shelf_audit_rows_june_2026
FROM store.shelf_audits
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01';

SELECT sku, name
FROM store.products
WHERE name ILIKE '%curd%';

SELECT COUNT(*) AS upi_refunds_2026
FROM payments.upi_refunds
WHERE requested_ts >= '2026-01-01' AND requested_ts < '2026-07-01';

SELECT COUNT(*) AS card_approved_june_2026
FROM payments.pos_payments
WHERE tender = 'card' AND till_status = 'approved' AND ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT table_name
FROM information_schema.tables
WHERE table_schema = 'store';

SELECT bill_id, attempt, ts, tender, till_status
FROM payments.pos_payments
LIMIT 20;

SELECT sku, name
FROM store.products
WHERE name ILIKE '%milk%';

SELECT COUNT(*) AS total_receipts, MIN(received_ts), MAX(received_ts)
FROM store.goods_receipts
WHERE received_ts >= '2026-05-01' AND received_ts < '2026-06-01';

SELECT DISTINCT reason
FROM store.write_offs
ORDER BY reason;

SELECT SUM(units_sold) AS total_units
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date <= '2026-06-30';

SELECT DISTINCT note
FROM payments.pos_payments
WHERE note ILIKE '%void%' OR note ILIKE '%supervisor%';

SELECT DISTINCT note
FROM payments.pos_payments
WHERE note IS NOT NULL;

SELECT *
FROM store.store_orders
LIMIT 10;

SELECT SUM(units) AS total_units
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT sku, gtin, name
FROM store.products
WHERE name ILIKE '%bag%' OR name ILIKE '%carry%' OR sku ILIKE '%bag%' OR sku ILIKE '%carry%';

SELECT DISTINCT sku_scanned, gtin_scanned
FROM store.pos_lines
LIMIT 50;

SELECT COUNT(*) AS total_counts
FROM store.stock_counts
WHERE count_ts >= '2026-01-01' AND count_ts < '2026-04-01';

SELECT sku, name, cost_inr, price_inr
FROM store.products
WHERE name ILIKE '%rice%' OR sku ILIKE '%rice%';
